package checker

import "github.com/microsoft/typescript-go/internal/ast"

type TemplateOwnerControl struct {
	Values                                                                                  []string
	DistinctOwners, IndependentLinks, ActivePop, RepeatTypes, SharedLiteral, HeadUncomputed bool
}

func (c *Checker) QualifyTemplateOwners(file *ast.SourceFile, reverse bool) TemplateOwnerControl {
	raw := c.getSymbolOfDeclaration(file.Statements.Nodes[0])
	head := c.cloneSymbol(raw)
	twin := c.cloneSymbol(raw)
	argument := c.getStringLiteralType("value")
	order := []*ast.Symbol{raw, head, twin}
	if reverse {
		order = []*ast.Symbol{twin, head, raw}
	}
	row := TemplateOwnerControl{DistinctOwners: raw != head && raw != twin && head != twin, IndependentLinks: true, ActivePop: true, RepeatTypes: true, SharedLiteral: true, HeadUncomputed: true}
	for _, owner := range order {
		links := c.typeAliasLinks.Get(owner)
		for _, other := range order {
			if owner != other {
				row.IndependentLinks = row.IndependentLinks && links != c.typeAliasLinks.Get(other)
			}
		}
	}
	// Hold a real private DeclaredType frame while forcing the other owners.
	// Native has no Rust template-only active set. This control qualifies the
	// selected alias identity, not equivalence of the two recursion protocols.
	if !c.pushTypeResolution(head, TypeSystemPropertyNameDeclaredType) {
		panic("head frame")
	}
	for _, owner := range []*ast.Symbol{raw, twin} {
		t := c.getTypeAliasInstantiation(owner, []*Type{argument}, nil)
		row.Values = append(row.Values, getStringLiteralValue(t))
	}
	row.HeadUncomputed = c.typeAliasLinks.Get(head).declaredType == nil
	row.ActivePop = c.popTypeResolution()
	var first *Type
	for _, owner := range order {
		t := c.getTypeAliasInstantiation(owner, []*Type{argument}, nil)
		row.Values = append(row.Values, getStringLiteralValue(t))
		row.RepeatTypes = row.RepeatTypes && t == c.getTypeAliasInstantiation(owner, []*Type{argument}, nil)
		if first == nil {
			first = t
		} else {
			row.SharedLiteral = row.SharedLiteral && first == t
		}
	}
	return row
}

